#import "../App/AI/Persona/TFAIPersona.h"
#import "../App/AI/Core/TFAIDeveloperPrompt.h"
static NSUInteger count;
static void Check(BOOL condition,NSString *name){if(!condition){NSLog(@"FAIL %@",name);exit(1);}count++;NSLog(@"PASS %@",name);}
static NSUInteger Blocks(NSString *s){return [s componentsSeparatedByString:TFAIPersonaBeginMarker].count-1;}
int main(int argc,const char **argv){@autoreleasepool{
 NSURL *url=[NSURL fileURLWithPath:@(argv[1])];NSString *phase=argc>2?@(argv[2]):@"core";TFAIPersonaStore *store=[[TFAIPersonaStore alloc]initWithURL:url];NSError *e=nil;
 if([phase isEqual:@"relaunch"]){Check(store.enabled&&store.personas.count==2&&[store.activeID isEqual:store.personas.lastObject.identifier],@"new process restores enabled, list and latest selection");Check([store.personas.lastObject.body isEqual:@"fixture 二🙂\n"],@"new process restores Unicode and newlines byte-exactly");return 0;}
 Check(!store.enabled&&!store.personas.count&&!store.builtins.count&&!store.activeID,@"fresh install has no presets, enabled off and no selected persona");
 Check([store.snapshot[@"includeDeveloperPrompt"] boolValue],@"fresh install keeps developer prompt by default");
 NSString *base=TFAIDeveloperPrompt(@{@"app":@"Dylix",@"mode":@"develop"},@[@{@"name":@"fixture_tool"}]);Check([[TFAIPersonaEngine build:base snapshot:store.snapshot] isEqual:base],@"disabled system is byte-for-byte unchanged");
 Check([store saveName:@"A" body:@"fixture 一" mode:@"prepend" identifier:nil error:&e],@"create first user persona");NSString *a=store.personas.firstObject.identifier;Check([[NSUUID alloc]initWithUUIDString:a]!=nil&&!store.personas.firstObject.isBuiltin,@"user record UUID and builtin flag");
 Check([store activateOnly:a error:&e]&&![TFAIPersonaEngine active:store.snapshot],@"selecting while globally off does not inject");Check([store setEnabled:YES error:&e],@"enable store");NSString *first=[TFAIPersonaEngine build:base snapshot:store.snapshot];Check([first hasPrefix:TFAIPersonaBeginMarker]&&[first hasSuffix:base],@"prepend puts persona before developer prompt");
 Check([store setIncludeDeveloperPrompt:NO error:&e],@"disable developer prompt in persona settings");NSString *only=[TFAIPersonaEngine build:base snapshot:store.snapshot];Check([only isEqual:@"fixture 一"],@"replacement sends only selected persona body without product marker");NSDictionary *onlyPreview=[TFAIPersonaEngine preview:base snapshot:store.snapshot];Check([onlyPreview[@"system"] isEqual:only]&&[onlyPreview[@"byteCount"] unsignedIntegerValue]==[only lengthOfBytesUsingEncoding:NSUTF8StringEncoding],@"replacement preview matches sent bytes");TFAIPersonaStore *onlyReloaded=[[TFAIPersonaStore alloc]initWithURL:url];Check(![onlyReloaded.snapshot[@"includeDeveloperPrompt"] boolValue]&&[[TFAIPersonaEngine build:base snapshot:onlyReloaded.snapshot] isEqual:only],@"replacement choice survives relaunch");Check([store setIncludeDeveloperPrompt:YES error:&e]&&[[TFAIPersonaEngine build:base snapshot:store.snapshot] isEqual:first],@"restoring developer prompt restores original composition");
 Check([store setIncludeDeveloperPrompt:NO error:&e],@"disable developer prompt for no-selection fallback");[store activateOnly:nil error:&e];Check([[TFAIPersonaEngine build:base snapshot:store.snapshot] isEqual:@""],@"no active persona omits developer prompt");NSDictionary *emptyPreview=[TFAIPersonaEngine preview:base snapshot:store.snapshot];Check([emptyPreview[@"byteCount"] unsignedIntegerValue]==0,@"empty system preview has zero bytes");[store activateOnly:a error:&e];[store setIncludeDeveloperPrompt:YES error:&e];
 Check(store.personas.firstObject.byteCount==[@"fixture 一" lengthOfBytesUsingEncoding:NSUTF8StringEncoding],@"model UTF-8 byteCount exact");
 Check([store saveName:@"B" body:@"fixture 二🙂\n" mode:@"append" identifier:nil error:&e],@"create second user persona");NSString *b=store.personas.lastObject.identifier;[store activateOnly:b error:&e];Check([store.activeID isEqual:b]&&[[TFAIPersonaEngine active:store.snapshot][@"id"] isEqual:b],@"activateOnly replaces prior selection");
 NSString *second=[TFAIPersonaEngine build:first snapshot:store.snapshot];Check(Blocks(second)==1&&![second containsString:@"fixture 一"]&&[second hasPrefix:base],@"strip old block before appending the new selection");Check([[TFAIPersonaEngine strip:second] isEqual:base],@"strip restores unmodified developer text");
 for(NSInteger i=0;i<3;i++){second=[TFAIPersonaEngine build:second snapshot:store.snapshot];Check(Blocks(second)==1,@"three consecutive compositions keep one marker block");}
 NSDictionary *preview=[TFAIPersonaEngine preview:base snapshot:store.snapshot];Check([preview[@"byteCount"] unsignedIntegerValue]==[second lengthOfBytesUsingEncoding:NSUTF8StringEncoding]&&[preview[@"system"] isEqual:second]&&[preview[@"activeCount"] isEqual:@1],@"preview matches actual system bytes including delimiters");
 [store saveName:@"B" body:store.personas.lastObject.body mode:@"replace" identifier:b error:&e];NSString *replaced=[TFAIPersonaEngine build:base snapshot:store.snapshot];Check(Blocks(replaced)==1&&![replaced containsString:base]&&[replaced containsString:@"fixture 二🙂"],@"replace removes only the supplied developer layer");
 [store setEnabled:NO error:&e];Check([[TFAIPersonaEngine build:second snapshot:store.snapshot] isEqual:base],@"disabled store removes old persona block");[store setEnabled:YES error:&e];[store activateOnly:nil error:&e];Check(!store.activeID&&[[TFAIPersonaEngine build:base snapshot:store.snapshot] isEqual:base],@"turning selected persona off leaves none active");
 Check(![store activateOnly:NSUUID.UUID.UUIDString error:&e]&&!store.activeID,@"unknown selection rejected without changing state");
 Check(![store saveName:@"bad" body:TFAIPersonaBeginMarker mode:@"append" identifier:nil error:&e],@"reserved markers rejected without silently rewriting user body");Check(![store saveName:@"bad" body:@"fixture" mode:@"bogus" identifier:nil error:&e],@"invalid mode rejected");
 NSString *spaced=@" \nbase\n ";for(NSString *mode in @[@"prepend",@"append"]){[store saveName:@"A" body:@"fixture" mode:mode identifier:a error:&e];[store activateOnly:a error:&e];Check([[TFAIPersonaEngine strip:[TFAIPersonaEngine build:spaced snapshot:store.snapshot]] isEqual:spaced],@"strip preserves developer leading and trailing whitespace");}
 Check([[TFAIPersonaEngine strip:[base stringByAppendingFormat:@"\n\n%@broken",TFAIPersonaBeginMarker]] isEqual:base],@"unfinished old marker block is removed");NSString *nested=[NSString stringWithFormat:@"%@\n\n%@outer%@inner%@tail%@",base,TFAIPersonaBeginMarker,TFAIPersonaBeginMarker,TFAIPersonaEndMarker,TFAIPersonaEndMarker];Check([[TFAIPersonaEngine strip:nested] isEqual:base],@"nested old blocks are stripped completely");
 TFAIPersonaStore *reloaded=[[TFAIPersonaStore alloc]initWithURL:url];Check(reloaded.enabled&&reloaded.personas.count==2&&[reloaded.activeID isEqual:a],@"JSON reload retains all state");[reloaded remove:a error:&e];Check(!reloaded.activeID&&reloaded.personas.count==1,@"delete active record clears selection");
 NSURL *bad=[[url URLByDeletingLastPathComponent] URLByAppendingPathComponent:@"bad.json"];[@"{broken" writeToURL:bad atomically:YES encoding:NSUTF8StringEncoding error:nil];TFAIPersonaStore *corrupt=[[TFAIPersonaStore alloc]initWithURL:bad];Check(corrupt.loadError&&!corrupt.enabled&&![corrupt setEnabled:YES error:&e],@"corrupt store fails closed and refuses overwriting original");Check([[NSString stringWithContentsOfURL:bad encoding:NSUTF8StringEncoding error:nil] isEqual:@"{broken"],@"corrupt JSON original preserved");
 NSURL *blocked=[bad URLByAppendingPathComponent:@"child/personas.json"];TFAIPersonaStore *failed=[[TFAIPersonaStore alloc]initWithURL:blocked];Check(![failed setEnabled:YES error:&e]&&!failed.enabled,@"failed disk writes do not change in-memory state");
 [store saveName:@"B" body:@"fixture 二🙂\n" mode:@"append" identifier:b error:&e];[store setEnabled:YES error:&e];[store activateOnly:b error:&e];NSLog(@"TOTAL %lu persona checks passed",(unsigned long)count);
}return 0;}
